#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-standards-compliance.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-standards-compliance — the ONE standards-checking gate.
 *
 * Per LOCK_FILES.yaml. Three checks:
 *   1. Shape     — every __specs__/standards-compliance.yaml MUST parse as a
 *                  flat key/value lock file (scalars + `key:` + `- item`
 *                  lists). Unreadable or malformed lock files fail.
 *   2. Presence  — every folder containing __specs__/ MUST have
 *                  __specs__/standards-compliance.yaml with:
 *                    status: locked
 *                    verified: "100%"
 *                    last_validated: <strict ISO-8601 UTC datetime, Z-suffixed>
 *   3. Freshness — folder git mtime MUST NOT exceed the lock file's git mtime.
 *                  If exceeded, the feature must be manually re-walked + re-stamped.
 *
 * `--full` adds a 4th, deeper freshness pass (folded in from the former
 * verify-standards-freshness gate): one `git log --format=%aI` per lock over the
 * source root, comparing the folder's most-recent commit author-date to the
 * lock's `last_validated` STRING (+30-min grace). It catches a stale stamp that
 * the git-mtime check (3) misses — a lock re-committed with its source but never
 * re-stamped. Slower (one git invocation per lock), so `--full` only; the default
 * chain keeps checks 1–3 for fast local iteration + pre-push.
 *
 * Per-rule grep gates are forbidden. The manual walk is the verification;
 * this script enforces that the walk happened.
 *
 * Usage (from project root):
 *   node scripts/verify/verify-standards-compliance.mjs [<source-root>] [--full]
 *
 * Root selection:
 *   - explicit CLI arg          → that single root (must exist; exit 2 otherwise)
 *   - FORCE_ROOT env var        → that single root (must exist; exit 2 otherwise)
 *   - default                   → `src/` (must exist; exit 2 otherwise) PLUS
 *                                 `scripts/` when present. Per SPEC_CONTRACT the
 *                                 per-feature verify scripts live in their own
 *                                 folders with __specs__/ + locks; both trees are
 *                                 lock-checked.
 *
 * Exits 0 when every feature passes all checks; non-zero otherwise.
 */
import { readdir, readFile, stat } from "node:fs/promises";
import { join, relative, resolve, dirname } from "node:path";
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";

// Shared ISO-8601 UTC matcher + the deep git-history freshness helpers — the
// single source in ../lib/locks.mjs. findAllLocks/checkFreshness/
// defaultGitLastCommit back the `--full` pass folded in from the former
// verify-standards-freshness gate.
import {
  ISO_UTC_RE,
  findAllLocks,
  checkFreshness,
  defaultGitLastCommit,
} from "../lib/locks.mjs";
import { loadLock, resolveLockFile } from "../lib/load-spec.mjs";

const REPO_ROOT = process.cwd();
// Arg parsing: `--full` is a flag (deep git-history freshness pass); the first
// non-flag positional is the source root. This keeps `--full` from being
// mistaken for the root (the freshness selftest drives `<gate> --full` with
// FORCE_ROOT set).
const CLI_ARGS = process.argv.slice(2);
const FULL = CLI_ARGS.includes("--full");
const POSITIONAL_ROOT = CLI_ARGS.find((a) => !a.startsWith("--"));
const EXPLICIT_ROOT = POSITIONAL_ROOT || process.env.FORCE_ROOT;
const SOURCE_ROOT = EXPLICIT_ROOT || "src";
const absRoot = resolve(REPO_ROOT, SOURCE_ROOT);

const IGNORE_DIRS = new Set([
  "node_modules",
  ".next",
  ".turbo",
  "coverage",
  "test-results",
  "playwright-report",
  ".git",
  "dist",
  "build",
  "out",
]);

/**
 * Required top-level SCALAR keys on every standards-compliance.yaml.
 */
const REQUIRED_KEYS = ["status", "verified", "last_validated"];

/**
 * Strict ISO-8601 UTC matcher: YYYY-MM-DDTHH:MM:SS(.sss)?Z.
 *
 * Anchored so a string with trailing garbage doesn't sneak through. The
 * Z suffix is required — lock files must be UTC per UTC_TIMESTAMPS.yaml.timestamps.
 */
// ISO_UTC_RE is imported from ../lib/locks.mjs (single source).

/**
 * Names of every standard registered in INDEX.yaml — the list every lock
 * file's standards: map must cover. Vendored copy preferred; ~/.claude
 * fallback. Zero-dep line parse (INDEX registers standards as 2-space-
 * indented UPPER_SNAKE keys under `standards:`). Cached after first call;
 * empty array (check disabled) when no INDEX.yaml is reachable.
 */
let _stdCache = null;
function registeredStandards() {
  if (_stdCache) return _stdCache;
  const idx = [
    join(REPO_ROOT, ".claude", "standards", "INDEX.yaml"),
    join(homedir(), ".claude", "standards", "INDEX.yaml"),
  ].find((p) => existsSync(p));
  if (!idx) { _stdCache = []; return _stdCache; }
  const text = readFileSync(idx, "utf8");
  const section = text.split(/^standards:\s*$/m)[1]?.split(/^[a-z_#]/m)[0] ?? "";
  _stdCache = [...section.matchAll(/^  ([A-Z][A-Z0-9_]+):\s*$/gm)].map((m) => m[1]);
  return _stdCache;
}

if (!existsSync(absRoot)) {
  process.stderr.write(`\n❌ verify-standards-compliance: source root '${SOURCE_ROOT}' not found at ${absRoot}\n`);
  process.exit(2);
}

// Default (no explicit root): also lock-check scripts/ when it exists —
// per-feature verify scripts carry __specs__/ + locks like any feature.
const roots = [absRoot];
if (!EXPLICIT_ROOT) {
  const scriptsRoot = resolve(REPO_ROOT, "scripts");
  if (existsSync(scriptsRoot)) roots.push(scriptsRoot);
}

const violations = [];
const lockedFeatures = [];

for (const root of roots) {
  await walk(root);
}

// ── --full: deep git-history freshness pass (folded from verify-standards-freshness) ──
// Default (no --full) leaves compliance's fast git-mtime freshness untouched.
// `--full` ADDS the former standalone gate's exact per-lock check: the folder's
// most-recent commit author-date (`git log -1 --format=%aI -- . :(exclude)<lock>`)
// vs the lock's `last_validated` STRING + a 30-min grace. This catches a stale
// lock that the git-mtime check MISSES — one whose `last_validated` string is
// old but which was re-committed alongside its source (equal mtimes ⇒ mtime-fresh,
// yet the stamp never advanced). Scope = the primary source root only (NOT the
// auto-added scripts/ root): the freshness gate's DEFAULT_ROOTS was [src], since
// vendored scripts/ locks are re-committed without re-stamping and carry no
// product-freshness meaning. Locks that fail presence/shape above are still
// checked here (mirrors the standalone gate: it parsed last_validated leniently
// and skipped only when the stamp was absent/unparseable).
if (FULL) {
  for (const lock of findAllLocks(absRoot)) {
    let lockContents;
    try {
      lockContents = readFileSync(lock, "utf8");
    } catch {
      continue; // read failure is the presence/shape checks' job to surface
    }
    const m = lockContents.match(/^\s*last_validated:\s*["']?([^"'\n]+?)["']?\s*$/m);
    if (!m) continue;
    const lastValidatedMs = Date.parse(m[1].trim());
    if (Number.isNaN(lastValidatedMs)) continue;
    const freshness = checkFreshness(lock, lastValidatedMs, {
      gitLastCommit: defaultGitLastCommit,
    });
    if (!freshness.ok) {
      violations.push(
        `${relative(REPO_ROOT, lock)}: STALE (git-history freshness, --full) — ${freshness.reason}: ${freshness.detail}`,
      );
    }
  }
}

async function walk(dir) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  // If this directory contains a __specs__ child, this IS a feature folder.
  if (entries.some((e) => e.isDirectory() && e.name === "__specs__")) {
    await auditFeature(dir);
  }
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    if (IGNORE_DIRS.has(e.name)) continue;
    if (e.name === "__specs__" || e.name === "__tests__") continue;
    await walk(join(dir, e.name));
  }
}

/**
 * Hand-rolled tiny YAML reader scoped to the lock-file shape: flat
 * key/value pairs PLUS list values declared as `key:` followed by
 * `  - <item>` lines (the LOCK_FILES.yaml schema's `flows`,
 * `tests`, `manual` fields). Quoted scalars + `#` comments + blank
 * lines all handled. Zero-dependency by design.
 *
 * Returned scalars are strings; returned lists are string arrays.
 *
 * @param {string} contents raw file contents
 * @returns {{ ok: true, value: Record<string, string | string[]> } | { ok: false, error: string }}
 */
function parseLockFile(contents) {
  if (typeof contents !== "string") {
    return { ok: false, error: "lock-file contents must be a string" };
  }
  /** @type {Record<string, string | string[]>} */
  const out = {};
  const lines = contents.split(/\r?\n/);
  /** @type {string | null} */
  let activeListKey = null;
  for (let i = 0; i < lines.length; i += 1) {
    const raw = lines[i];
    const trimmed = raw.trim();
    if (trimmed === "") {
      activeListKey = null;
      continue;
    }
    if (trimmed.startsWith("#")) continue;
    // List-item line: `  - <value>` — when activeListKey is set, append.
    if (trimmed.startsWith("- ") || trimmed === "-") {
      if (activeListKey === null) {
        return {
          ok: false,
          error: `line ${String(i + 1)}: list-item with no preceding 'key:' line`,
        };
      }
      const item = trimmed.startsWith("- ")
        ? stripQuotes(trimmed.slice(2).trim())
        : "";
      const existing = /** @type {string[]} */ (out[activeListKey]);
      existing.push(item);
      continue;
    }
    activeListKey = null;
    const colon = trimmed.indexOf(":");
    if (colon === -1) {
      return {
        ok: false,
        error: `line ${String(i + 1)}: expected '<key>: <value>'`,
      };
    }
    const key = trimmed.slice(0, colon).trim();
    let value = trimmed.slice(colon + 1).trim();
    // Strip inline `# comment` from unquoted scalar values.
    if (!value.startsWith('"') && !value.startsWith("'")) {
      const hashIdx = value.indexOf("#");
      if (hashIdx !== -1) value = value.slice(0, hashIdx).trim();
    }
    value = stripQuotes(value);
    if (key === "") {
      return { ok: false, error: `line ${String(i + 1)}: empty key` };
    }
    if (value === "") {
      // Empty scalar declares a list context — subsequent `- <item>`
      // lines append to this key.
      out[key] = [];
      activeListKey = key;
    } else {
      out[key] = value;
    }
  }
  return { ok: true, value: out };
}

/**
 * Strips matching single- or double-quotes from a scalar's edges.
 *
 * @param {string} v
 * @returns {string}
 */
function stripQuotes(v) {
  if (
    (v.startsWith('"') && v.endsWith('"')) ||
    (v.startsWith("'") && v.endsWith("'"))
  ) {
    return v.slice(1, -1);
  }
  return v;
}

async function auditFeature(featureDir) {
  const rel = relative(REPO_ROOT, featureDir);
  // Dual-format lock: standards-compliance.md (fenced block) wins, else legacy .yaml.
  const specsDir = join(featureDir, "__specs__");
  const scYaml = resolveLockFile(specsDir);
  const violationsBefore = violations.length;

  // Presence check
  if (!existsSync(scYaml)) {
    violations.push(`${rel}: missing __specs__/standards-compliance.yaml`);
    return;
  }

  // Shape check — the lock file must parse as flat key/value YAML (from the
  // spec.md fenced block or the legacy .yaml, resolved by loadLock).
  let parsed;
  try {
    parsed = loadLock(specsDir);
  } catch (err) {
    violations.push(
      `${rel}: cannot read standards-compliance.yaml — ${err instanceof Error ? err.message : String(err)}`,
    );
    return;
  }
  if (!parsed.ok) {
    violations.push(`${rel}: standards-compliance.yaml invalid YAML — ${parsed.error}`);
    return;
  }

  // Required keys must be present AND scalar (a list where a scalar is
  // expected counts as missing).
  for (const k of REQUIRED_KEYS) {
    const v = parsed.value[k];
    if (v === undefined || Array.isArray(v)) {
      violations.push(`${rel}: standards-compliance.yaml lacks scalar '${k}'`);
    }
  }
  if (violations.length !== violationsBefore) return;

  const status = parsed.value["status"];
  const verified = parsed.value["verified"];
  const lastValidated = /** @type {string} */ (parsed.value["last_validated"]);

  if (status !== "locked") {
    violations.push(`${rel}: standards-compliance.yaml status="${String(status)}" (expected "locked")`);
  }
  if (verified !== "100%") {
    violations.push(`${rel}: standards-compliance.yaml verified=${JSON.stringify(verified)} (expected "100%")`);
  }
  // standards: map — EVERY registered standard deliberately stamped, none
  // omitted. Verdict enum: "100%" | "NOT REQUIRED (<reason>)". (The flat
  // parser folds the indented map entries into top-level keys.)
  // browser_validated — BROWSER_VALIDATION.yaml: a feature that ships UI cannot
  // lock without a real-browser walk stamp (ISO-8601 UTC, stamped by Mode A).
  const bvFeatureDir = dirname(dirname(scYaml));
  let shipsUi = false;
  try {
    const stack = [bvFeatureDir];
    while (stack.length && !shipsUi) {
      const d = stack.pop();
      for (const e of await readdir(d, { withFileTypes: true })) {
        if (e.isDirectory()) {
          if (e.name === "__stories__") { shipsUi = true; break; }
          if (e.name !== "__specs__" && e.name !== "__tests__" && !IGNORE_DIRS.has(e.name)) stack.push(join(d, e.name));
        } else if (e.name.endsWith(".tsx")) { shipsUi = true; break; }
      }
    }
  } catch { /* unreadable -> treated as UI-less */ }
  if (shipsUi) {
    const bv = parsed.value["browser_validated"];
    if (bv === undefined || Array.isArray(bv)) {
      violations.push(`${rel}: ships UI but standards-compliance.yaml lacks browser_validated — no real-browser walk, no stamp (BROWSER_VALIDATION.yaml)`);
    } else if (!ISO_UTC_RE.test(bv)) {
      violations.push(`${rel}: browser_validated="${bv}" is not a valid ISO-8601 UTC datetime`);
    } else {
      // Tightening: the stamp must be backed by REAL walk records — LOCAL machines
      // only. Walk records are git-ignored local evidence (MANUAL_FLOWS writes_to);
      // CI checkouts never have them, and browser walks cannot run in CI. CI
      // validates the committed artifacts (stamp format + lock freshness).
      if (process.env.CI) { /* record evidence is local-only */ } else {
      // (record checks below) Every
      // manual/<flow>.md the feature ships needs a manual-results record
      // (<repo>/manual-results/<stem>.<iso>.json, git-ignored) no older than
      // 60 min before browser_validated (BROWSER_VALIDATION.yaml.evidence).
      try {
        const manualDir = join(bvFeatureDir, "__specs__", "manual");
        const stems = existsSync(manualDir)
          ? (await readdir(manualDir)).filter((f) => f.endsWith(".md")).map((f) => f.slice(0, -3))
          : [];
        if (stems.length > 0) {
          const resultsDir = [join(REPO_ROOT, "manual-results"), join(REPO_ROOT, "..", "..", "manual-results")].find((d) => existsSync(d));
          const bvMs = Date.parse(bv);
          for (const stem of stems) {
            const records = resultsDir
              ? (await readdir(resultsDir)).filter((f) => f.startsWith(`${stem}.`) && f.endsWith(".json"))
              : [];
            let newest = 0;
            for (const r of records) newest = Math.max(newest, (await stat(join(resultsDir, r))).mtimeMs);
            if (records.length === 0) {
              violations.push(`${rel}: browser_validated stamped but NO manual-results record for flow "${stem}" (expected <repo>/manual-results/${stem}.<iso>.json) — the walk must be real (BROWSER_VALIDATION.yaml.evidence)`);
            } else if (newest < bvMs - 3600000) {
              violations.push(`${rel}: manual-results record for flow "${stem}" is older than 60 min before browser_validated — stale walk evidence`);
            }
          }
        }
      } catch { /* unreadable manual dir -> no record check */ }
      }
    }
  }

  for (const std of registeredStandards()) {
    const verdict = parsed.value[std];
    if (verdict === undefined || Array.isArray(verdict)) {
      violations.push(`${rel}: standards-compliance.yaml standards: map is missing '${std}' — every registered standard must be stamped 100% or NOT REQUIRED`);
    } else if (!/^(100%|NOT REQUIRED\b.*)$/.test(verdict)) {
      violations.push(`${rel}: standards-compliance.yaml standards.${std}="${verdict}" — only "100%" or "NOT REQUIRED" are valid verdicts (reason lives in the companion md files)`);
    }
  }
  // Strict ISO-8601 UTC — Z suffix required per UTC_TIMESTAMPS.yaml.timestamps. A merely
  // Date-parseable value (date-only, numeric offset) does NOT satisfy.
  if (!ISO_UTC_RE.test(lastValidated)) {
    violations.push(
      `${rel}: standards-compliance.yaml last_validated="${lastValidated}" is not a valid ISO-8601 UTC datetime (YYYY-MM-DDTHH:MM:SSZ)`,
    );
    return;
  }
  const validatedMs = Date.parse(lastValidated);
  if (Number.isNaN(validatedMs)) {
    violations.push(`${rel}: standards-compliance.yaml last_validated="${lastValidated}" did not parse as a Date`);
    return;
  }

  // Freshness check — comparison reference is the standards-compliance.yaml's
  // own git mtime, NOT the last_validated string. The string is required for
  // human readability + the explicit lock contract; the freshness gate uses
  // git mtimes so re-stamping + committing in the same commit Just Works.
  //
  // Rule: every other file under the feature folder MUST have a git mtime ≤
  // standards-compliance.yaml's git mtime. If they were committed together,
  // mtimes are equal → fresh. If a code file was committed AFTER the YAML
  // was last stamped, freshness fails — exactly when re-walking is needed.
  //
  // Untracked files fall back to fs mtime so newly-added files still trigger
  // freshness when the lock isn't refreshed.
  const stampGitMtime = await gitMtime(scYaml);
  const stampMtime = stampGitMtime > 0 ? stampGitMtime : validatedMs;
  const folderMtime = await deepGitMtime(featureDir);
  if (folderMtime > stampMtime) {
    const drift = Math.round((folderMtime - stampMtime) / 1000);
    violations.push(
      `${rel}: STALE — feature content most-recently modified ${drift}s after standards-compliance.yaml was last committed/stamped. Re-walk + re-stamp + commit together.`,
    );
    return;
  }

  // Only count as locked + fresh if no violation was added during this audit.
  if (violations.length === violationsBefore) {
    lockedFeatures.push(rel);
  }
}

/**
 * Read the latest git-committed time across every file in `dir`
 * (recursive), excluding IGNORE_DIRS and the standards-compliance.yaml
 * itself. Falls back to filesystem mtime for untracked files. Uses
 * `git log -1 --format=%ct -- <path>` (commit unix time) when the file
 * is tracked.
 */
import { execFileSync } from "node:child_process";

async function gitMtime(file) {
  try {
    const out = execFileSync("git", ["log", "-1", "--format=%ct", "--", file], {
      cwd: REPO_ROOT,
      encoding: "utf-8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    if (/^\d+$/.test(out)) return parseInt(out, 10) * 1000;
  } catch {}
  try {
    const s = await stat(file);
    return s.mtimeMs;
  } catch {}
  return 0;
}

async function deepGitMtime(dir) {
  // Collect file paths first.
  const files = [];
  await scan(dir);
  async function scan(d) {
    let entries;
    try {
      entries = await readdir(d, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      if (IGNORE_DIRS.has(e.name)) continue;
      const p = join(d, e.name);
      if (e.isDirectory()) {
        await scan(p);
      } else if (e.isFile()) {
        if (e.name === "standards-compliance.yaml") continue;
        files.push(p);
      }
    }
  }

  let max = 0;
  for (const f of files) {
    let stamp = 0;
    try {
      const out = execFileSync("git", ["log", "-1", "--format=%ct", "--", f], {
        cwd: REPO_ROOT,
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "ignore"],
      }).trim();
      if (/^\d+$/.test(out)) stamp = parseInt(out, 10) * 1000;
    } catch {
      // not in a git repo or other failure — fall back to fs mtime
    }
    if (stamp === 0) {
      try {
        const s = await stat(f);
        stamp = s.mtimeMs;
      } catch {}
    }
    if (stamp > max) max = stamp;
  }
  return new Date(max);
}

// ---------- output ----------

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-standards-compliance — ${lockedFeatures.length} feature(s) locked + fresh\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `\n❌ verify-standards-compliance: ${violations.length} violation(s)\n`,
);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(
  `\n   ${lockedFeatures.length} feature(s) passed.\n`,
);
process.exit(1);
